          .map((sectorId) => {
            const sector = allSectorsList.find((s) => s.id === sectorId);
            const keywords = sector && Array.isArray(sector.keywords) ? sector.keywords : [];
            return keywords.length ? keywords.join(' OR ') : '';
          })
          .filter(Boolean);
        for (const query of sectorQueries) {
